use hyperreal::Real;
fn main() {
    std::thread::spawn(|| {
        let huge: Real = "1e320".parse().unwrap();
        let x = (-huge).exp().unwrap();
        eprintln!("exp constructed");
        let a = x.atan().unwrap();
        eprintln!("atan constructed");
        assert!(a.certified_rational_interval(-128).is_some());
        eprintln!("composed enclosure completed");
    }).join().unwrap();
}
